import { apiFetch } from "@/shared/api/apiClient";

// One section of a knowledge file: uploaded, or generated by the server (see GENERATED_SOURCES).
export type KnowledgeChunk = {
  id: string;
  source: string;
  title: string;
  text: string;
};

export type UploadFileResult = {
  fileName: string;
  sections: number;
  error: string | null;
};

export type KnowledgeSearchResult = {
  score: number;
  id: string;
  source: string;
  title: string;
  text: string;
};

// Built from the doctors, specialties and hospital settings and kept in sync by the server, so they cannot be deleted or uploaded.
export const GENERATED_SOURCES = ["doctor-settings.md", "specialty-settings.md", "hospital-settings.md"];

export const getChunks = () => apiFetch<KnowledgeChunk[]>("/knowledge/chunks");

export function uploadKnowledge(files: File[]) {
  const form = new FormData();
  files.forEach((file) => form.append("files", file));
  return apiFetch<UploadFileResult[]>("/knowledge/upload", { method: "POST", body: form });
}

export const loadDefaultKnowledge = () => apiFetch<UploadFileResult[]>("/knowledge/load-defaults", { method: "POST" });

export const syncSettings = () => apiFetch<void>("/knowledge/sync-settings", { method: "POST" });

export const deleteKnowledgeSource = (source: string) =>
  apiFetch<{ deleted: number }>(`/knowledge/sources/${encodeURIComponent(source)}`, { method: "DELETE" });

export const searchKnowledge = (query: string) =>
  apiFetch<KnowledgeSearchResult[]>(`/knowledge/search?q=${encodeURIComponent(query)}&k=5`);
